#include "PerceptionDivergenceDetector.h"
#include <algorithm>
namespace dnxr { PerceptionDivergenceReport PerceptionDivergenceDetector::detect(const std::vector<ExpectedPerception>& expected,const ClosedLoopFeedback& actual,float stress,float latencyMs) const { PerceptionDivergenceReport r; const float missing=actual.available?0.0f:0.5f; r.divergenceScore=std::clamp(missing+(1.0f-actual.perceptionConfidence)*0.35f+stress*0.25f+latencyMs/250.0f,0.0f,1.0f); if(!expected.empty()&&r.divergenceScore>0.4f) r.affectedModalities.push_back(FullDiveModality::RealityAnchor); if(r.divergenceScore>0.75f){r.mustStop=true;r.likelyCause="feedback_or_physiology_diverged";r.recommendedCorrection="emergency_stop_or_decompression";} else if(r.divergenceScore>0.4f){r.likelyCause="perception_mismatch";r.recommendedCorrection="reduce_intensity_and_anchor";} return r; } }
